import{_ as e,o as i,c as s,al as t}from"./chunks/framework.q0M0_7A-.js";const k=JSON.parse('{"title":"Installation","description":"","frontmatter":{},"headers":[],"relativePath":"installation.md","filePath":"installation.md","lastUpdated":null}'),n={name:"installation.md"};function l(o,a,r,h,p,d){return i(),s("div",null,[...a[0]||(a[0]=[t(`<h1 id="Installation" tabindex="-1">Installation <a class="header-anchor" href="#Installation" aria-label="Permalink to &quot;Installation {#Installation}&quot;">​</a></h1><h2 id="1.-Install-Julia" tabindex="-1">1. Install Julia <a class="header-anchor" href="#1.-Install-Julia" aria-label="Permalink to &quot;1. Install Julia {#1.-Install-Julia}&quot;">​</a></h2><p>Install Julia 1.10 or later with <a href="https://julialang.org/downloads/" target="_blank" rel="noreferrer">juliaup</a>, the official installer. For writing and running scripts, <a href="https://www.julia-vscode.org/" target="_blank" rel="noreferrer">VS Code with the Julia extension</a> works well: it runs a script line by line and shows plots in a side pane.</p><h2 id="2.-Make-a-project-folder" tabindex="-1">2. Make a project folder <a class="header-anchor" href="#2.-Make-a-project-folder" aria-label="Permalink to &quot;2. Make a project folder {#2.-Make-a-project-folder}&quot;">​</a></h2><p>Julia keeps the packages of a project in an <em>environment</em>, much like a Python virtual environment. Make a folder for your work, open a terminal in it and start Julia with that folder as the environment:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>julia --project=.</span></span></code></pre></div><h2 id="3.-Add-Mocca-and-CairoMakie" tabindex="-1">3. Add Mocca and CairoMakie <a class="header-anchor" href="#3.-Add-Mocca-and-CairoMakie" aria-label="Permalink to &quot;3. Add Mocca and CairoMakie {#3.-Add-Mocca-and-CairoMakie}&quot;">​</a></h2><p>At the <code>julia&gt;</code> prompt:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Pkg</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Pkg</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">add</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(url </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;https://github.com/sintefmath/Mocca.jl&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, rev </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;main&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Pkg</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">add</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;CairoMakie&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">Install from GitHub for now</p><p>These docs describe the development version of Mocca. The version in Julia&#39;s package registry (0.1.0) has the earlier interface, without <code>read_process</code>, <code>Process</code> or <code>cyclic_steady_state</code>, so install from GitHub as above until the next release.</p></div><p>CairoMakie is only needed to save plots to files and to run the examples that draw their own figures.</p><p>The next time you start Julia in the folder with <code>julia --project=.</code>, the packages are there.</p><h2 id="4.-Check-that-it-works" tabindex="-1">4. Check that it works <a class="header-anchor" href="#4.-Check-that-it-works" aria-label="Permalink to &quot;4. Check that it works {#4.-Check-that-it-works}&quot;">​</a></h2><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Mocca</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">library_processes</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span></code></pre></div><p>The first <code>using Mocca</code> in a new session compiles the code, and the first simulation compiles the solver, which can take a few minutes. Later runs in the same session take seconds, so keep the session open while you work.</p><h2 id="5.-Run-an-example" tabindex="-1">5. Run an example <a class="header-anchor" href="#5.-Run-an-example" aria-label="Permalink to &quot;5. Run an example {#5.-Run-an-example}&quot;">​</a></h2><p>Each example in these docs is a Julia script in the <a href="https://github.com/sintefmath/Mocca.jl/tree/main/examples" target="_blank" rel="noreferrer"><code>examples</code> folder</a> on GitHub. Download one into your project folder and run it from the Julia prompt:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">include</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;getting_started.jl&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>or open it in VS Code and run it a block at a time with Shift+Enter.</p><p>Next: <a href="/Mocca.jl/previews/PR52/examples/getting_started#Getting-started">Getting started</a> reads a process from Mocca&#39;s library, runs it to cyclic steady state, measures it and exports the results to a spreadsheet.</p>`,20)])])}const u=e(n,[["render",l]]);export{k as __pageData,u as default};
